const CACHE='fn-cds-demo-v48';self.addEventListener('install',e=>e.waitUntil(caches.open(CACHE).then(c=>c.addAll(['./','./index.html','./app.js','./install-app.js','./account-access.js','./mobile-dashboard.js','./mobile-dashboard.css','./messages.js','./voice-calls.js','./team-workspace.js','./knowledge-core.js','./knowledge-workbench.js','./traceable-orders.js','./remote-escalation.js','./baseline-approval.js','./upgrade.js','./interactions.js','./assessment.js','./demo-cases.js','./review-workflow.js','./care.js','./safety-center.js','./scope-evidence.js','./orders-metrics-core.js','./orders-quality.js','./quarter-model.js','./quarter-dashboard.js','./ceo-print.js','./ceo-report.html','./print-launcher.js','./refinement.css','./rules.js','./patients.json','./workbook-data.json','./workbook-core.js','./workbook-ui.js','./workspace-core.js','./workspace-ui.js','./workspace-ui.css','./action-cases.json','./action-core.js','./action-registry-core.js','./action-ui.js','./action-ui.css','./therapy-review-core.js','./therapy-review-ui.js','./task-guidance-core.js','./task-guidance-ui.js','./clinical-guidelines.js','./clinical-guidelines-ui.js','./antibiotic-selection-core.js','./antibiotic-orders-core.js','./antibiotic-orders-ui.js','./antibiotic-orders.css','./intake-core.js','./intake-ui.js','./intake-ui.css','./dynamic-core.js','./dynamic-ui.js','./dynamic-ui.css','./dynamic-examples.json','./dynamic-validation.js','./dynamic-validation.json','./icon.svg','./icon-192.png','./icon-512.png','./manifest.json']))));self.addEventListener('activate',e=>e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k!==CACHE).map(k=>caches.delete(k))))));self.addEventListener('fetch',e=>{if(!new URL(e.request.url).pathname.startsWith('/api/')&&e.request.method==='GET'&&new URL(e.request.url).origin===self.location.origin)e.respondWith(fetch(e.request).catch(()=>caches.match(e.request).then(r=>r||(e.request.mode==='navigate'?caches.match('./index.html'):Response.error()))))});

self.addEventListener('install',()=>self.skipWaiting());
self.addEventListener('activate',e=>e.waitUntil(self.clients.claim()));
self.addEventListener('push',e=>{let data={};try{data=e.data?.json()||{}}catch{}e.waitUntil(self.registration.showNotification('FN Clinical CDS',{body:data.kind==='registration'?'A new user has registered. Open Registered users to view the account.':'You have a new message. Open the app and sign in to read it.',icon:'/icon-192.png',badge:'/icon-192.png',tag:data.messageId||'fn-message',data:{url:data.kind==='registration'?'/#requests':'/#messages'}}))});
self.addEventListener('notificationclick',e=>{e.notification.close();e.waitUntil((async()=>{const target=e.notification.data?.url==='/#requests'?'/#requests':'/#messages';const tabs=await clients.matchAll({type:'window',includeUncontrolled:true});for(const t of tabs){if(new URL(t.url).origin===self.location.origin){await t.navigate(target);return t.focus()}}return clients.openWindow(target)})())});
